    const float a0_c0_z0_ch = fma_rn(xl0, yl0, 0.0f);
    const float a0_c0_z0_cl1 = fma_rn(xl0, yl0, -a0_c0_z0_ch);
    const float a0_c0_z0_tl0 = fma_rn(xl1, yl1, 0.0f);
    const float a0_c0_z0_tl1 = fma_rn(xl0, yl1, a0_c0_z0_tl0);
