    const float a0_c0_wu_s_ab = abs_bits(a0_c0_d);
    const bool a0_c0_wu_s_m = a0_c0_wu_s_ab > a0_c0_wu_s_aa;
    const float a0_c0_wu_s_h = a0_c0_wu_s_m ? a0_c0_d : a0_c0_z1;
