    const float a0_c0_wu_e = a0_c0_wu_s_l - a0_c0_wu_s_z;
    const bool a0_c0_wu_n = a0_c0_wu_e > 0.0f;
    const float a0_c0_wu_q = next_up_bits(a0_c0_wu_s);
    const float a0_c0_wu = a0_c0_wu_n ? a0_c0_wu_q : a0_c0_wu_s;
