    const float b0_c0_z0_z = b0_c0_z0 - b0_c0_z0_ch;
    const float b0_c0_z1 = b0_c0_z0_cl3 - b0_c0_z0_z;
    const float b0_c0_z0_az = abs_bits(b0_c0_z0);
