            const float x0 = x0_in[i_];
            const float x1 = x1_in[i_];
            const float y0 = y0_in[i_];
            const float y1 = y1_in[i_];
            // (step_z0, step_z1) = sub_2_2(x0, x1, y0, y1)
            const float step_n0 = -y0;
            const float step_n1 = -y1;
